 public VideiraSite(bool demo=false){preview=demo;Text="Videira Site 3.0 — Administração";Size=new Size(1366,900);MinimumSize=new Size(1024,720);StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",9.5f);AutoScaleMode=AutoScaleMode.Dpi;DoubleBuffered=true;BackColor=Color.FromArgb(240,240,241);Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);Build();ShowPage("Painel");FormClosing+=(s,e)=>{if(busy||!Discard())e.Cancel=true;};FormClosed+=(s,e)=>api.Dispose();}
 Button ActionButton(string text,Func<Task> action,bool primary=false){var b=new Button{Text=text,AutoSize=true,Height=34,MinimumSize=new Size(90,34),FlatStyle=FlatStyle.Flat,BackColor=primary?blue:Color.White,ForeColor=primary?Color.White:blue,Padding=new Padding(10,3,10,3),Margin=new Padding(0,0,8,8)};b.FlatAppearance.BorderColor=primary?blue:line;b.Click+=async(s,e)=>await Run(action);return b;}
 async Task Run(Func<Task> action){if(busy)return;busy=true;UseWaitCursor=true;body.Enabled=false;sidebar.Enabled=false;try{await action();}catch(Exception ex){Notify(ex is HttpRequestException?"Não foi possível conectar. Confira a internet. O salvamento não foi confirmado.":ex.Message,true);}finally{body.Enabled=true;sidebar.Enabled=true;UseWaitCursor=false;busy=false;}}
