 sidebar=new Panel{Dock=DockStyle.Fill,BackColor=dark,Margin=Padding.Empty};shell.Controls.Add(sidebar,0,1);var menu=new FlowLayoutPanel{Dock=DockStyle.Top,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoSize=true,Padding=new Padding(0,12,0,0)};sidebar.Controls.Add(menu);foreach(var item in new[]{new[]{"Painel","▣"},new[]{"Produtos","▤"},new[]{"Adicionar produto","＋"},new[]{"Categorias","≡"},new[]{"Mídia","▧"},new[]{"Configurações","⚙"}}){string name=item[0];var button=new Button{Text=item[1]+"   "+name,Width=190,Height=44,TextAlign=ContentAlignment.MiddleLeft,FlatStyle=FlatStyle.Flat,ForeColor=Color.White,BackColor=dark,Padding=new Padding(12,0,0,0),Margin=Padding.Empty};button.FlatAppearance.BorderSize=0;button.Click+=(s,e)=>{if(!busy&&Discard()){dirty=false;ShowPage(name);}};menu.Controls.Add(button);nav[name]=button;}var visit=new LinkLabel{Text="Ver site ↗",ForeColor=Color.LightGray,LinkColor=Color.LightGray,VisitedLinkColor=Color.LightGray,AutoSize=true,Margin=new Padding(18,26,0,0)};visit.LinkClicked+=(s,e)=>System.Diagnostics.Process.Start("https://videira-loja.vercel.app/");menu.Controls.Add(visit);var logout=new LinkLabel{Text="Sair da conta",LinkColor=Color.LightGray,AutoSize=true,Margin=new Padding(18,20,0,0)};logout.LinkClicked+=async(s,e)=>await Run(async()=>{if(!Discard())return;await api.Logout();products.Clear();categories.Clear();dirty=false;account.Text="Conta do administrador";ShowPage("Painel");});menu.Controls.Add(logout);
 var main=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2,ColumnCount=1,Margin=Padding.Empty};main.RowStyles.Add(new RowStyle(SizeType.Percent,100));main.RowStyles.Add(new RowStyle(SizeType.Absolute,58));shell.Controls.Add(main,1,1);body=new Panel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(28,24,28,24),Margin=Padding.Empty};body.Resize+=(s,e)=>FitPage();main.Controls.Add(body,0,0);notice=new Label{Text="Videira Site • Catálogo conectado à loja online",Dock=DockStyle.Fill,Padding=new Padding(20,12,20,0),BackColor=Color.White};main.Controls.Add(notice,0,1);}
 Panel Card(string heading,int height){var card=new Panel{Width=Math.Max(650,body.ClientSize.Width-78),Height=height,BackColor=Color.White,BorderStyle=BorderStyle.FixedSingle,Margin=new Padding(0,0,0,20),Padding=new Padding(20)};card.Controls.Add(new Label{Text=heading,Font=new Font("Segoe UI",12,FontStyle.Bold),AutoSize=true,Location=new Point(20,18)});return card;}
 void ShowPage(string name){SetShell(api.Connected||preview);page=name;foreach(var n in nav)n.Value.BackColor=n.Key==name?blue:dark;if(!api.Connected&&!preview){LoginPage();return;}if(name=="Painel")Dashboard();else if(name=="Produtos")ProductsPage();else if(name=="Adicionar produto")Editor(null);else if(name=="Categorias")CategoriesPage();else if(name=="Mídia")MediaPage();else SettingsPage();}
 void RecoveryDialog(){using(var d=new Form{Text="Recuperar acesso — Videira Site",Width=670,Height=390,StartPosition=FormStartPosition.CenterParent,Font=Font,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){var note=new Label{Text="1. Solicite o e-mail.\n2. No e-mail, copie o endereço do botão de recuperação sem abrir o link.\n3. Cole abaixo e defina sua nova senha.",Location=new Point(20,20),Size=new Size(610,70)};d.Controls.Add(note);var send=new Button{Text="Enviar e-mail de recuperação",Location=new Point(20,95),Size=new Size(245,32)};d.Controls.Add(send);var link=new TextBox{Location=new Point(20,166),Width=610};d.Controls.Add(new Label{Text="Endereço do link recebido no e-mail",Location=new Point(20,141),AutoSize=true});d.Controls.Add(link);var newpass=new TextBox{Location=new Point(20,224),Width=380,UseSystemPasswordChar=true};d.Controls.Add(new Label{Text="Nova senha — pelo menos 10 caracteres",Location=new Point(20,199),AutoSize=true});d.Controls.Add(newpass);var reset=new Button{Text="Definir nova senha",Location=new Point(20,265),Size=new Size(170,32)};d.Controls.Add(reset);var result=new Label{Location=new Point(20,305),Size=new Size(610,45)};d.Controls.Add(result);send.Click+=async(a,b)=>{send.Enabled=false;try{await api.SendRecovery();result.Text="E-mail solicitado. Confira também a caixa de spam.";}catch(Exception ex){result.Text=ex.Message;}finally{send.Enabled=true;}};reset.Click+=async(a,b)=>{reset.Enabled=false;try{await api.Recover(link.Text,newpass.Text);newpass.Clear();link.Clear();result.Text="Senha atualizada. Feche esta janela e entre com a nova senha.";}catch(Exception ex){result.Text=ex.Message;}finally{reset.Enabled=true;}};d.ShowDialog(this);}}
 DataGridView Grid(){var g=new DataGridView{ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,MultiSelect=true,SelectionMode=DataGridViewSelectionMode.FullRowSelect,RowHeadersVisible=false,BackgroundColor=Color.White,BorderStyle=BorderStyle.FixedSingle,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,EnableHeadersVisualStyles=false,ColumnHeadersHeight=42};g.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(246,247,247);g.ColumnHeadersDefaultCellStyle.ForeColor=Color.FromArgb(44,51,56);g.DefaultCellStyle.SelectionBackColor=Color.FromArgb(227,241,248);g.DefaultCellStyle.SelectionForeColor=Color.FromArgb(0,90,140);g.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(249,249,249);g.GridColor=Color.FromArgb(230,230,230);g.RowTemplate.Height=44;return g;}
